import {t,setLanguage} from './coastal-i18n.js';
export function startScreen({node,onStart,initial={}}){
 let world=initial.world??'uk',language=initial.language??'en',mode=initial.mode??'normal';
 const root=node('section',null,'coastal-start-screen');
 function render(){setLanguage(language);root.lang=language;root.replaceChildren();const header=node('header');header.append(node('span','🧭 '+t('EXPEDITION PASSPORT')),node('h1',t('Choose your world')),node('p',t('Connect places. Discover geography.')));root.append(header);const grid=node('div',null,'coastal-world-grid');
  for(const [id,name,src]of [['uk','United Kingdom',new URL('../assets/coastal/stations/london.jpg',import.meta.url).href],['kyrgyzstan','Kyrgyzstan',new URL('../assets/coastal/kyrgyzstan/world-cover.jpg',import.meta.url).href]]){const tile=node('button',null,'coastal-world-tile');tile.type='button';tile.dataset.world=id;tile.setAttribute('aria-pressed',String(world===id));const picture=node('img');picture.src=src;picture.alt=t(name);tile.append(picture,node('strong',t(name)),node('small',t(id==='uk'?'Islands · capitals · coastal connections':'Mountains · lakes · Silk Road journeys')));tile.onclick=()=>{world=id;render();};grid.append(tile);}
  const outlines=['M10 5 L55 2 L78 22 L69 39 L58 42 L45 88 L28 95 L17 66 L4 39 Z','M18 2 L80 10 L61 38 L47 45 L61 64 L47 98 L28 79 L31 55 L12 28 Z','M10 18 L36 2 L76 15 L96 45 L74 72 L38 62 L20 85 L4 43 Z'];for(const path of outlines){const tile=node('div',null,'coastal-world-tile coastal-world-coming');tile.setAttribute('aria-disabled','true');const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 100 100');const p=document.createElementNS(svg.namespaceURI,'path');p.setAttribute('d',path);svg.append(p);tile.append(svg,node('strong',t('Coming soon')));grid.append(tile);}root.append(grid);
  const options=node('div',null,'coastal-start-options'),langs=node('label',t('Language')),select=node('select');select.setAttribute('aria-label',t('Language'));select.dataset.language='';for(const [id,name]of [['en','English'],['ru','Русский'],['ky','Кыргызча']]){const option=node('option',name);option.value=id;option.selected=id===language;select.append(option);}select.onchange=()=>{language=select.value;render();};langs.append(select);options.append(langs);const difficulty=node('fieldset');difficulty.append(node('legend',t('Difficulty')));for(const [id,label]of [['normal','Normal'],['hard','Hard']]){const b=node('button',t(label));b.type='button';b.dataset.mode=id;b.setAttribute('aria-pressed',String(mode===id));b.onclick=()=>{mode=id;render();};difficulty.append(b);}difficulty.append(node('p',t(mode==='normal'?'Normal: build and learn at your own pace.':'Hard: geography events disrupt your network.')));options.append(difficulty);root.append(options);const start=node('button',t('Start journey'),'coastal-start-journey');start.type='button';start.dataset.startJourney='';start.onclick=()=>onStart({world,language,mode});root.append(start);
 }
 render();return root;
}
